/* ═════════════ 7.2 — Bảng tra một trang ═════════════ */
const B_BANG_TRA = bash("# Bảng tra của tôi — VS Code · IntelliJ · terminal · regex (bản 24/11/2026)\n\n## VS Code\n| Việc | Win/Linux | macOS |\n|---|---|---|\n| Mở tệp theo tên | Ctrl+P | ⌘P |\n| Chạy mọi lệnh | Ctrl+Shift+P | ⇧⌘P |\n| Symbol cả dự án | Ctrl+T | ⌘T |\n| Tới định nghĩa / xem tại chỗ | F12 / Alt+F12 | F12 / ⌥F12 |\n| Mọi nơi dùng | Shift+Alt+F12 | ⌥⇧F12 |\n| Quay lại chỗ cũ | Alt+← | ⌃- |\n| Đổi tên an toàn | F2 | F2 |\n| Quick Fix / tách hàm | Ctrl+. | ⌘. |\n| Thêm con trỏ chỗ khớp kế / mọi chỗ | Ctrl+D / Ctrl+Shift+L | ⌘D / ⇧⌘L |\n| Chuyển / nhân đôi dòng | Alt+↑↓ / Shift+Alt+↑↓ | ⌥↑↓ / ⇧⌥↑↓ |\n| Tìm trong mọi tệp (Alt+R = regex) | Ctrl+Shift+F | ⇧⌘F |\n| Terminal | Ctrl+` | ⌃` |\n\n## IntelliJ IDEA\n| Việc | Win/Linux | macOS |\n|---|---|---|\n| Tìm mọi thứ / tìm lệnh | Shift Shift / Ctrl+Shift+A | ⇧⇧ / ⇧⌘A |\n| Tới class / tệp | Ctrl+N / Ctrl+Shift+N | ⌘O / ⇧⌘O |\n| Tới khai báo / lớp cài | Ctrl+B / Ctrl+Alt+B | ⌘B / ⌥⌘B |\n| Find Usages | Alt+F7 | ⌥F7 |\n| Gợi ý tại chỗ | Alt+Enter | ⌥↩ |\n| Rename / Change Signature | Shift+F6 / Ctrl+F6 | ⇧F6 / ⌘F6 |\n| Tách method / biến | Ctrl+Alt+M / Ctrl+Alt+V | ⌥⌘M / ⌥⌘V |\n| Sinh mã / tới test | Alt+Insert / Ctrl+Shift+T | ⌘N / ⇧⌘T |\n| Chạy theo ngữ cảnh / Run Anything | Ctrl+Shift+F10 / Ctrl Ctrl | ⌃⇧R / ⌃⌃ |\n| Breakpoint / qua dòng / vào hàm | Ctrl+F8 / F8 / F7 | ⌘F8 / F8 / F7 |\n| Tính biểu thức khi dừng | Alt+F8 | ⌥F8 |\n| Commit / Push | Ctrl+K / Ctrl+Shift+K | ⌘K / ⌘⇧K |\n| Cửa sổ Git (Log, Console) | Alt+9 | ⌘9 |\n\n## Terminal (chạy được — kiem-bang-tra.sh thử từng dòng)\n```sh\nrg -n 'findUserById' src                     # tìm chữ, có số dòng\nrg -nw completeTask src test                 # nguyên từ: không dính markTaskDone\nrg -l 'TODO' -g '*.js' src                   # chỉ tên tệp, lọc theo đuôi\nfd -e js . src                               # tìm tệp theo đuôi (Ubuntu: fdfind)\ngit log --oneline -5                         # 5 commit gần nhất\ngit diff --stat HEAD~1                       # commit cuối đổi những tệp nào\ngit log -L '/function formatDueDate/,+4:src/utils/format.js' --oneline   # lịch sử MỘT hàm\ngit stash list                               # có gì đang cất tạm không\nnode -e \"fetch('https://example.invalid').catch(e=>console.log('mạng:', e.cause?.code))\"   # máy có ra mạng không\njq -r '.scripts | keys[]' package.json       # lệnh npm có sẵn\nls -la ~/.ssh 2>/dev/null | head -3          # khoá SSH (KHÔNG chép nội dung ra đâu)\n```\n\n## Regex (thử bằng rg; trong IDE bật .* rồi dán phần mẫu)\n```sh\nrg -n \"'\\d{4}-\\d{2}-\\d{2}'\" src              # ngày ISO trong chuỗi\nrg -nP \"(?<=status: )'[A-Z]+'\" src           # lookbehind cần -P\nrg -n 'console\\.log\\(' src                   # dấu chấm và ngoặc phải thoát\nrg -n '^\\s*export function \\w+' src          # đầu dòng + khoảng trắng\nrg -or '$2/$1' \"'(\\d{4})-(\\d{2})-\\d{2}'\" src     # nhóm bắt + đổi thứ tự (chỉ xem, không ghi)\n```\nThay trong IDE: tìm `'(\\d{4})-(\\d{2})-(\\d{2})'` → thay `'$3/$2/$1'` (VS Code và IntelliJ đều dùng `$1`). Phạm vi: chỉ `src/`.\nNguy hiểm: `(a+)+`, `(.*)*`, `(\\s|\\S)*` trên chuỗi người dùng gửi lên ⇒ ReDoS (bài 4.5).\n");
const B_IN = bash("// in-mot-trang.mjs <bang-tra.md> — đổi bảng tra Markdown thành HTML khổ A4 hai cột, in ra PDF bằng Chrome headless, báo số trang.\n// Không cần thư viện: chỉ hiểu đúng thứ bảng tra dùng (#, ##, bảng |…|, khối ```sh, đoạn văn, `mã`).\n// CHROME=đường-dẫn nếu Chrome không nằm ở chỗ quen. Không có Chrome ⇒ mở tệp .html, Ctrl+P / ⌘P → Save as PDF.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst md = process.argv[2];\nif (!md) { console.error('cách dùng: node in-mot-trang.mjs bang-tra.md'); process.exit(2); }\nconst esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\nconst inl = (s) => esc(s).replace(/`([^`]+)`/g, '<code>$1</code>');\nconst dong = fs.readFileSync(md, 'utf8').split('\\n');\nlet html = '', i = 0;\nwhile (i < dong.length) {\n  const l = dong[i];\n  if (l.startsWith('```')) {\n    const khoi = []; i++;\n    while (i < dong.length && !dong[i].startsWith('```')) khoi.push(dong[i++]);\n    html += `<pre>${esc(khoi.join('\\n'))}</pre>\\n`; i++; continue;\n  }\n  if (l.startsWith('|')) {\n    const hang = [];\n    while (i < dong.length && dong[i].startsWith('|')) hang.push(dong[i++]);\n    const o = (h) => h.slice(1, -1).split('|').map((c) => c.trim());\n    html += '<table><tr>' + o(hang[0]).map((c) => `<th>${inl(c)}</th>`).join('') + '</tr>\\n'\n      + hang.slice(2).map((h) => '<tr>' + o(h).map((c) => `<td>${inl(c)}</td>`).join('') + '</tr>').join('\\n') + '</table>\\n';\n    continue;\n  }\n  if (l.startsWith('## ')) html += `<h2>${inl(l.slice(3))}</h2>\\n`;\n  else if (l.startsWith('# ')) html += `<h1>${inl(l.slice(2))}</h1>\\n`;\n  else if (l.trim()) html += `<p>${inl(l)}</p>\\n`;\n  i++;\n}\nconst css = `@page{size:A4;margin:8mm}body{font:7.6pt/1.25 system-ui,sans-serif;columns:2;column-gap:6mm;margin:0}\nh1{column-span:all;font-size:11pt;margin:0 0 2mm}h2{font-size:8.6pt;margin:2mm 0 1mm;break-after:avoid}\ntable{border-collapse:collapse;width:100%;break-inside:avoid}td,th{border:1px solid #bbb;padding:.4mm 1mm;text-align:left}\nth{background:#eee}pre{font:6.6pt/1.25 monospace;background:#f6f6f6;padding:1mm;white-space:pre-wrap;margin:0 0 1mm;break-inside:avoid}\np{margin:.6mm 0}code{font:6.8pt monospace}`;\nconst goc = md.replace(/\\.md$/, '');\nfs.writeFileSync(goc + '.html', `<!doctype html><meta charset=\"utf-8\"><style>${css}</style>\\n${html}`);\nconst chrome = process.env.CHROME || ['/usr/bin/google-chrome', '/usr/bin/chromium',\n  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',\n  'C:\\\\Program Files\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe'].find((p) => fs.existsSync(p));\nif (!chrome) { console.log(`ghi ${goc}.html — không thấy Chrome: mở tệp này, Ctrl+P / ⌘P → Save as PDF`); process.exit(0); }\nexecFileSync(chrome, ['--headless', '--disable-gpu', '--no-pdf-header-footer', `--print-to-pdf=${goc}.pdf`,\n  'file://' + path.resolve(goc + '.html')], { stdio: 'ignore' });\n// đếm trang không cần pdfinfo: mỗi trang PDF có đúng một đối tượng /Type /Page\nconst trang = (fs.readFileSync(goc + '.pdf', 'latin1').match(/\\/Type\\s*\\/Page[^s]/g) || []).length;\nconsole.log(`ghi ${goc}.pdf — ${trang} trang${trang === 1 ? ' ✔' : ' ✘ (cần đúng 1: bớt dòng bạn không dùng)'}`);\nprocess.exit(trang === 1 ? 0 : 1);\n");
const B_KIEM_BT = bash("#!/usr/bin/env bash\n# kiem-bang-tra.sh <bang-tra.md> <dự-án> — chạy THỬ từng dòng lệnh trong các khối ```sh của bảng tra, trên BẢN SAO của dự án\n# (không đụng dự án thật), quét bí mật, đếm hàng. Dòng nào lỗi hoặc không khớp gì (exit ≠ 0) = dòng chưa được chứng minh.\nset -uo pipefail\nMD=$(cd \"$(dirname \"$1\")\" && pwd)/$(basename \"$1\"); DA=$(cd \"$2\" && pwd)\nTAM=$(mktemp -d); trap 'rm -rf \"$TAM\"' EXIT\ncp -a \"$DA\" \"$TAM/da\"; cd \"$TAM/da\" || exit 2\nok=0; loi=0; trong=0\nwhile IFS= read -r l; do\n  case \"$l\" in '```sh'*) trong=1; continue ;; '```'*) trong=0; continue ;; esac\n  [ $trong = 1 ] && [ -n \"${l// }\" ] || continue\n  timeout 10 bash -c \"$l\" </dev/null >/dev/null 2>&1; e=$?\n  if [ $e = 0 ]; then ok=$((ok + 1)); printf '  ok     %s\\n' \"${l%%#*}\"\n  else loi=$((loi + 1)); printf '  LỖI(%s) %s\\n' \"$e\" \"${l%%#*}\"; fi\ndone < \"$MD\"\necho \"lệnh chạy được: $ok · lỗi/không khớp: $loi\"\nBM=$(grep -nE 'ghp_[A-Za-z0-9]{20}|AKIA[0-9A-Z]{16}|BEGIN [A-Z ]*PRIVATE KEY|(password|passwd|token|secret)[[:space:]]*[=:][[:space:]]*[^[:space:]<]{6,}' \"$MD\")\n[ -n \"$BM\" ] && { echo \"BÍ MẬT trong bảng tra:\"; echo \"$BM\"; }\nH=$(grep -c '^| ' \"$MD\"); echo \"hàng phím tắt (kể cả dòng tiêu đề bảng): $H\"\n[ $loi = 0 ] && [ -z \"$BM\" ]\n");
