const B_TIM_GOI = bash("// tim-goi.mjs <thư-mục labflow-mini> <tên-hàm> [tên-mới] — gọi THẲNG TypeScript Language Service (thứ đứng sau Shift+F12 / F2 của VS Code\n// với JS/TS) để liệt kê tham chiếu; có tên-mới thì tính các chỗ F2 sẽ sửa và ghi luôn (như bấm Enter trong hộp Rename).\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { createRequire } from 'node:module';\nconst ts = createRequire(import.meta.url)(process.env.TS || 'typescript');\nconst [goc, ten, moi] = process.argv.slice(2);\nconst tep = fs.readdirSync(goc, { recursive: true }).filter((f) => /\\.(js|jsx)$/.test(f) && !f.includes('node_modules')).map((f) => path.join(goc, f));\nconst host = {\n  getScriptFileNames: () => tep, getScriptVersion: () => '1', getCurrentDirectory: () => goc,\n  getScriptSnapshot: (f) => fs.existsSync(f) ? ts.ScriptSnapshot.fromString(fs.readFileSync(f, 'utf8')) : undefined,\n  getCompilationSettings: () => ({ allowJs: true, checkJs: false, jsx: ts.JsxEmit.Preserve, module: ts.ModuleKind.NodeNext, moduleResolution: ts.ModuleResolutionKind.NodeNext }),\n  getDefaultLibFileName: (o) => ts.getDefaultLibFilePath(o), fileExists: fs.existsSync, readFile: (f) => fs.readFileSync(f, 'utf8'),\n};\nconst ls = ts.createLanguageService(host);\nconst dinh = tep.find((f) => fs.readFileSync(f, 'utf8').includes('export function ' + ten));\nconst pos = fs.readFileSync(dinh, 'utf8').indexOf('function ' + ten) + 9;\nconst vitri = (f, s) => { const t = fs.readFileSync(f, 'utf8'); const d = t.slice(0, s).split('\\n'); return `${path.relative(goc, f)}:${d.length}: ${t.split('\\n')[d.length - 1].trim()}`; };\nconst refs = ls.getReferencesAtPosition(dinh, pos) || [];\nconsole.log(`Find All References ${ten}: ${refs.length} chỗ`);\nfor (const r of refs) console.log('  ' + vitri(r.fileName, r.textSpan.start));\nif (moi) {\n  const sua = ls.findRenameLocations(dinh, pos, false, false, {}) || [];\n  console.log(`Rename → ${moi}: sửa ${sua.length} chỗ (bỏ qua chú thích và chuỗi)`);\n  const theoTep = {};\n  for (const s of sua) (theoTep[s.fileName] ||= []).push(s.textSpan);\n  for (const [f, ds] of Object.entries(theoTep)) {\n    let t = fs.readFileSync(f, 'utf8');\n    for (const d of ds.sort((a, b) => b.start - a.start)) t = t.slice(0, d.start) + moi + t.slice(d.start + d.length);\n    fs.writeFileSync(f, t);\n  }\n}\n");
const B_DUNG73 = bash("#!/usr/bin/env bash\n# dung-73.sh <thư-mục> — bản labflow-mini cho câu phỏng vấn \"tìm nơi gọi\": thêm một chú thích nhắc tên hàm và một lời gọi động bằng chuỗi\nset -euo pipefail\nD=$1; cd \"$D\"\ncat > src/services/report.service.js <<'JS'\nimport * as userService from './user.service.js';\n\n// TODO: findUserById trả null khi không có — đừng dùng ở đây nữa\nconst HAM_TIM = 'findUserById';             // tên hàm đọc từ cấu hình\n\nexport function nguoiPhuTrach(task) {\n  return userService[HAM_TIM](task.assigneeId);\n}\nJS\ncat > test/report.service.test.js <<'JS'\nimport test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { nguoiPhuTrach } from '../src/services/report.service.js';\n\ntest('nguoiPhuTrach tra ve dung nguoi', () => {\n  assert.equal(nguoiPhuTrach({ assigneeId: 2 }).name, 'Binh');\n});\nJS\n");
const B_REDOS73 = bash("// redos73.mjs — câu phỏng vấn \"regex này có vấn đề gì\": đo mẫu kiểm tên hiển thị trên chuỗi xấu, so với bản viết lại\nconst xau = /^([a-zA-Z0-9]+\\s?)*$/;\nconst tot = /^[a-zA-Z0-9]+(?:\\s[a-zA-Z0-9]+)*\\s?$/;\nfor (const n of [18, 20, 22, 24, 26]) {\n  const s = 'a'.repeat(n) + '!';\n  for (const [ten, re] of [['xấu', xau], ['tốt', tot]]) {\n    const t = process.hrtime.bigint(); const k = re.test(s);\n    console.log(`n=${n} ${ten}: ${k} sau ${(Number(process.hrtime.bigint() - t) / 1e6).toFixed(1)} ms`);\n  }\n}\nconsole.log('cùng kết quả trên chuỗi hợp lệ:', ['Nguyen Van An', 'abc ', 'a  b', ''].map((s) => `${JSON.stringify(s)} ${xau.test(s)}/${tot.test(s)}`).join(' · '));\n");
